cd /app/logs/ci; python3 - <<'E'
import re,glob,collections
d=collections.defaultdict(collections.Counter)
for f in sorted(glob.glob('*')):
    t=open(f).read()
    for blk in re.split(r'\n---- ',t)[1:]:
        lines=blk.strip().split('\n')
        if re.search('stock_report|putaway_plan|roundtrip|aging_report',lines[0]):
            b='\n'.join(l for l in lines[1:] if not l.startswith('result'))
            b=re.sub(r'File.*\n','',b)
            d[lines[0]][b]+=1
for k,v in d.items():
    print('=====',k)
    for m,c in v.items(): print(c,m[-700:]);print('--')
E
